<script setup lang="ts">
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue'; import { ArrowUpRight, Pencil, Search, Users } from 'lucide-vue-next';
import { useRoute, useRouter } from 'vue-router'; import MemberEntryModal from './MemberEntryModal.vue';
import { api, errorMessage } from '../../services/api'; import { useAuthStore } from '../../stores/auth'; import { useLocale } from '../../composables/useLocale';
import AppTable from '../../components/tables/AppTable.vue'; import AppSelect from '../../components/ui/AppSelect.vue'; import AppButton from '../../components/ui/AppButton.vue'; import StatusBadge from '../../components/ui/StatusBadge.vue'; import MemberAvatar from '../../components/ui/MemberAvatar.vue'; import { date } from '../../utils/format'; import { statusOptions, type Member } from './types';
const route = useRoute(); const router = useRouter(); const notice = ref(''); const photoWarning = ref('');
const entryOpen = computed(() => auth.can('members.write') && typeof route.query.entry === 'string');
const entryId = computed(() => route.query.entry && route.query.entry !== 'new' ? String(route.query.entry) : undefined);
function openEntry(id = 'new') { void router.push({ query: { ...route.query, entry: id } }); }
async function closeEntry() { const { entry, ...query } = route.query; await router.replace({ query }); }
async function saved(member: Member, uploadError?: string) { notice.value = `${member.fullName} saved successfully.`; photoWarning.value = uploadError ? `Profile saved, but photo change failed: ${uploadError}. Open the profile to retry.` : ''; await closeEntry(); await load(); }
const auth = useAuthStore(); const { t } = useLocale(); const rows = ref<Member[]>([]); const total = ref(0); const pages = ref(1); const page = ref(1); const pageSize = ref('10'); const search = ref(''); const status = ref(''); const sort = ref('createdAt'); const direction = ref('desc'); const busy = ref(false); const error = ref(''); let timer: ReturnType<typeof setTimeout>; let sequence = 0;
const columns = [{ key: 'fullName', label: 'Member', sortable: true }, { key: 'memberNo', label: 'Member number', sortable: true }, { key: 'phone', label: 'Contact details' }, { key: 'joinedAt', label: 'Joined' }, { key: 'status', label: 'Status' }, { key: 'action', label: '' }];
async function load() {
  const request = ++sequence; busy.value = true; error.value = '';
  try { const { data } = await api.get('/members', { params: { page: page.value, pageSize: pageSize.value, search: search.value, status: status.value || undefined, sort: sort.value, direction: direction.value } }); if (request === sequence) { rows.value = data.items; total.value = data.total; pages.value = data.pages; } }
  catch (e) { if (request === sequence) error.value = errorMessage(e); } finally { if (request === sequence) busy.value = false; }
}
function goPage(value: number) { page.value = value; void load(); }
function sortBy(key: string) { direction.value = sort.value === key && direction.value === 'asc' ? 'desc' : 'asc'; sort.value = key; goPage(1); }
watch(search, () => { clearTimeout(timer); timer = setTimeout(() => goPage(1), 300); });
watch([status, pageSize], () => goPage(1)); onMounted(load); onBeforeUnmount(() => { clearTimeout(timer); sequence++; });
</script>
<template><div class="page-heading"><div><span class="eyebrow">PEOPLE MAKE THE SOCIETY</span><h1>{{ t('Member directory') }}<span class="heading-dot">.</span></h1><p>Keep every member’s details together and up to date.</p></div><AppButton v-if="auth.can('members.write')" @click="openEntry()">+ {{ t('Add member') }}</AppButton></div><div v-if="notice" class="alert success" role="status">{{ notice }}</div><div v-if="photoWarning" class="alert error" role="alert">{{ photoWarning }}</div><section class="panel directory"><div class="directory-heading"><h2>All members <span class="count-pill">{{ total }}</span></h2><span class="muted small-text">Your community, in one place</span></div><div class="filter-row"><label class="search-field"><Search :size="18" /><input v-model="search" :aria-label="t('Search members')" placeholder="Search name, number, phone or email…"></label><AppSelect v-model="status" label="Membership status" class="compact-field" :options="[{ value: '', label: t('All statuses') }, ...statusOptions]" /><AppSelect v-model="pageSize" label="Per page" class="compact-field page-size" :options="[{ value: '10', label: '10 / page' }, { value: '25', label: '25 / page' }, { value: '50', label: '50 / page' }]" /></div><div v-if="error" class="alert error" role="alert">{{ error }} <AppButton variant="ghost" @click="load">Retry</AppButton></div><AppTable v-else :rows="rows" :columns="columns" :total="total" :page="page" :pages="pages" :loading="busy" :sort="sort" :direction="direction" @page="goPage" @sort="sortBy"><template #cell-fullName="{ row }"><RouterLink :to="`/members/${row.id}`" class="member-cell"><MemberAvatar :name="row.fullName" :document-id="row.documents[0]?.id" /><strong>{{ row.fullName }}</strong></RouterLink></template><template #cell-memberNo="{ row }"><span class="member-number">{{ row.memberNo }}</span></template><template #cell-phone="{ row }"><div class="contact-cell"><span>{{ row.phone }}</span><small>{{ row.email || 'No email added' }}</small></div></template><template #cell-joinedAt="{ row }">{{ date(row.joinedAt) }}</template><template #cell-status="{ row }"><StatusBadge :status="row.status" /></template><template #cell-action="{ row }"><div class="button-row"><button v-if="auth.can('members.write')" class="icon-button" :aria-label="`Edit ${row.fullName}`" @click="openEntry(row.id)"><Pencil :size="18" /></button><RouterLink :to="`/members/${row.id}`" class="icon-button" :aria-label="`View ${row.fullName}`"><ArrowUpRight :size="18" /></RouterLink></div></template><template #empty><div class="empty-state"><Users :size="32" /><h3>{{ search || status ? 'No matching members' : 'No members yet' }}</h3><p>{{ search || status ? 'Try a different search or status.' : 'Add your first member to begin your directory.' }}</p></div></template></AppTable></section><p class="under-table-note">Member records are private and accessible according to your role.</p><MemberEntryModal :open="entryOpen" :member-id="entryId" @close="closeEntry" @saved="saved" /></template>
